/**
 * Asset Generator (Super Prompt §9.8 - Phase G).
 *
 * Generates real pixel-art assets for mods, modpacks, and servers:
 * - Item textures (swords, tools, food, etc.)
 * - Block textures (blocks, ores, etc.)
 * * Item models (JSON)
 * * Block models (JSON)
 * * Blockstates (JSON)
 * * Lang files (en_us.json, pt_br.json)
 * * pack.mcmeta
 *
 * All textures are real pixel art generated by the Rust perimeter.
 */

import { invoke } from "@tauri-apps/api/core";
import { writeProjectFile } from "@/services/projects/projectsService";

export interface AssetDefinition {
  id: string;
  type: "item" | "block";
  style: "gem" | "sword" | "ingot" | "orb" | "apple" | "book" | "wand" | "panel" | "bricks" | "planks" | "ore";
  primary: string;
  secondary: string;
  frames?: number; // 1 = static, 2-8 = animated
  displayName: string;
}

export interface AssetGenerationResult {
  assetId: string;
  type: string;
  path: string;
  bytes: number;
}

export interface AssetPackResult {
  packPath: string;
  fileCount: number;
  totalBytes: number;
  assets: AssetGenerationResult[];
  summary: string;
}

export interface AssetPackOptions {
  storageBase: string;
  projectRel: string;
  packName: string;
  packDescription?: string;
  modId: string;
  language: "pt_br" | "en_us";
  assets: AssetDefinition[];
  generateSounds: boolean;
}

/**
 * Generate a complete asset pack for a mod or modpack
 */
export async function createAssetPack(options: AssetPackOptions): Promise<AssetPackResult> {
  const {
    storageBase,
    projectRel,
    packName,
    packDescription = "A VOXEL asset pack",
    modId,
    language = "pt_br",
    assets,
    generateSounds = true,
  } = options;

  const packRel = `${projectRel}/assets/${modId}`;
  const texturesItemRel = `${packRel}/textures/item`;
  const texturesBlockRel = `${packRel}/textures/block`;
  const modelsItemRel = `${packRel}/models/item`;
  const modelsBlockRel = `${packRel}/models/block`;
  const blockstatesRel = `${packRel}/blockstates`;
  const langRel = `${packRel}/lang`;

  const writtenAssets: AssetGenerationResult[] = [];
  let totalBytes = 0;

  // ---- 1. pack.mcmeta ----
  const packMeta = JSON.stringify(
    {
      pack: {
        pack_format: 15,
        description: `${packName} - ${packDescription}`,
      },
    },
    null,
    2,
  );
  await writeProjectFile(storageBase, `${projectRel}/pack.mcmeta`, packMeta);
  totalBytes += packMeta.length;

  // ---- 2. Lang files ----
  const langEntries: Record<string, string> = {};
  for (const asset of assets) {
    langEntries[`item.${asset.id.replace(/_/g, "_")}`] = asset.displayName;
    langEntries[`block.${asset.id.replace(/_/g, "_")}`] = asset.displayName;
  }
  await writeProjectFile(storageBase, `${langRel}/${language}.json`, JSON.stringify(langEntries, null, 2));
  totalBytes += JSON.stringify(langEntries, null, 2).length;

  // Also write en_us as fallback
  if (language !== "en_us") {
    await writeProjectFile(storageBase, `${langRel}/en_us.json`, JSON.stringify(langEntries, null, 2));
    totalBytes += JSON.stringify(langEntries, null, 2).length;
  }

  // ---- 3. Item textures (real pixel art via Rust) ----
  for (const asset of assets) {
    if (asset.type === "item") {
      const result = await invoke<{ wrotePath?: string; pngBase64?: string }>("generate_item_texture", {
        storageBase,
        projectRel: texturesItemRel,
        modId,
        itemId: asset.id,
        style: asset.style,
        primary: asset.primary,
        secondary: asset.secondary,
        assetKind: "item",
        frames: asset.frames,
        previewOnly: false,
      });
      if (result.wrotePath) {
        totalBytes += result.pngBase64 ? Math.round((result.pngBase64.length * 3) / 4) : 0;
        writtenAssets.push({
          assetId: asset.id,
          type: "item",
          path: result.wrotePath,
          bytes: result.pngBase64 ? Math.round((result.pngBase64.length * 3) / 4) : 0,
        });
      }
    }
  }

  // ---- 4. Block textures ----
  for (const asset of assets) {
    if (asset.type === "block") {
      const result = await invoke<{ wrotePath?: string; pngBase64?: string }>("generate_item_texture", {
        storageBase,
        projectRel: texturesBlockRel,
        modId,
        itemId: asset.id,
        style: asset.style,
        primary: asset.primary,
        secondary: asset.secondary,
        assetKind: "block",
        previewOnly: false,
      });
      if (result.wrotePath) {
        totalBytes += result.pngBase64 ? Math.round((result.pngBase64.length * 3) / 4) : 0;
        writtenAssets.push({
          assetId: asset.id,
          type: "block",
          path: result.wrotePath,
          bytes: result.pngBase64 ? Math.round((result.pngBase64.length * 3) / 4) : 0,
        });
      }
    }
  }

  // ---- 5. Item models ----
  for (const asset of assets.filter(a => a.type === "item")) {
    const model = JSON.stringify(
      {
        parent: "item/generated",
        textures: {
          layer0: `${modId}:item/${asset.id}`,
        },
      },
      null,
      2,
    );
    await writeProjectFile(storageBase, `${modelsItemRel}/${asset.id}.json`, model);
    totalBytes += model.length;
  }

  // ---- 6. Block models + blockstates ----
  for (const asset of assets.filter(a => a.type === "block")) {
    const model = JSON.stringify(
      {
        parent: "block/cube_all",
        textures: {
          all: `${modId}:block/${asset.id}`,
        },
      },
      null,
      2,
    );
    await writeProjectFile(storageBase, `${modelsBlockRel}/${asset.id}.json`, model);
    totalBytes += model.length;

    const blockstate = JSON.stringify(
      {
        variants: {
          "": { model: `${modId}:block/${asset.id}` },
        },
      },
      null,
      2,
    );
    await writeProjectFile(storageBase, `${blockstatesRel}/${asset.id}.json`, blockstate);
    totalBytes += blockstate.length;
  }

  // ---- 7. Sounds (skeleton) ----
  if (generateSounds) {
    const soundsJson = JSON.stringify(
      {
        [`${modId}:item_pickup`]: {
          sounds: [{ name: `${modId}:item_pickup`, stream: false }],
          subtitle: `${modId}:subtitle.item_pickup`,
        },
      },
      null,
      2,
    );
    await writeProjectFile(storageBase, `${packRel}/sounds.json`, soundsJson);
    totalBytes += soundsJson.length;
  }

  return {
    packPath: `${storageBase}/${projectRel}`,
    fileCount: writtenAssets.length + assets.length * 2 + 4,
    totalBytes,
    assets: writtenAssets,
    summary: `Asset pack "${packName}" created with ${assets.length} assets (${writtenAssets.length} textures, ${assets.length * 2} models/blockstates)`,
  };
}

/**
 * Generate a single item texture
 */
export async function generateItemTexture(options: {
  storageBase: string;
  projectRel: string;
  modId: string;
  itemId: string;
  style: string;
  primary: string;
  secondary: string;
  assetKind: "item" | "block";
  frames?: number;
}): Promise<{ path: string; bytes: number }> {
  const result = await invoke<{ wrotePath?: string; pngBase64?: string }>("generate_item_texture", {
    storageBase: options.storageBase,
    projectRel: `${options.projectRel}/textures/${options.assetKind}`,
    modId: options.modId,
    itemId: options.itemId,
    style: options.style,
    primary: options.primary,
    secondary: options.secondary,
    assetKind: options.assetKind,
    frames: options.frames,
    previewOnly: false,
  });

  if (!result.wrotePath) {
    throw new Error(`Failed to generate texture for ${options.itemId}`);
  }

  return {
    path: result.wrotePath,
    bytes: result.pngBase64 ? Math.round((result.pngBase64.length * 3) / 4) : 0,
  };
}
